import{_ as r,a0 as d,w as s,s as l,ao as a,I as p,x as o,a1 as n,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"如何在 Ubuntu 中再次登錄時還原上次運行的應用 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 中再次登錄時還原上次運行的應用 | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 中再次登錄時還原上次運行的應用 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 中再次登錄時還原上次運行的應用 | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150119 How to Remember and Restore Running Applications on Next Logon","title":"如何在 Ubuntu 中再次登錄時還原上次運行的應用","tag":"201504","desc":""},"relativePath":"201504/20150119 How to Remember and Restore Running Applications on Next Logon.md","filePath":"[post].md"}'),u={name:"201504/20150119 How to Remember and Restore Running Applications on Next Logon.md"};function c(g,e,m,b,f,x){const t=d("Link");return s(),l("div",null,[e[13]||(e[13]=a(`<h1 id="如何在-ubuntu-中再次登錄時還原上次運行的應用" tabindex="-1">如何在 Ubuntu 中再次登錄時還原上次運行的應用 <a class="header-anchor" href="#如何在-ubuntu-中再次登錄時還原上次運行的應用" aria-label="Permalink to “如何在 Ubuntu 中再次登錄時還原上次運行的應用”">​</a></h1><p>在你的 Ubuntu 裏，如果你需要處理一些工作，你並不需要關閉正運行着的那些應用，只需要管理一下窗口，並打開那些工作需要的應用就行。然而，如果你需要離開處理些別的事情或你的機器電量低使得你必須馬上關閉電腦，這些程序可能就需要關閉終止了。不過幸運的是，你可以讓 Ubuntu 記住所有你正運行的應用並在你下一次登錄時還原它們。</p><p>###自動保存會話</p><p>現在，為了讓我們的 Ubuntu 記住當前會話中正運行的應用並在我們下一次登錄時還原它們，我們將會使用到 <code>dconf-editor</code>。這個工具代替了前一個 Ubuntu 版本里安裝的 <code>gconf-editor</code>，但默認情況下現在這個 Ubuntu 版本(注：這裏指的是 Ubuntu 14.04 LTS) 並沒有安裝。為了安裝 <code>dconf-editor</code>， 你需要運行 <code>sudo apt-get install dconf-editor</code>命令：</p><pre><code>$ sudo apt-get install dconf-tools
</code></pre><p>一旦 <code>dconf-editor</code> 安裝完畢，你就可以從應用菜單（注：這裏指的是 Unity Dash）裏打開它，或者你可以通過直接在終端裏運行，或使用 <code>alt+f2</code> 運行下面的命令來啓動它:</p><pre><code>$ dconf-editor
</code></pre><p>在 “dconf Editor” 窗口中，在左邊窗格里點擊臨近 &quot;org&quot; 的右箭頭來展開這個選項的分支。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/dconf-editor-clicking-org-300x146.png" alt="Dconf Editor Apps, org"></p><p>然後在 “org” 下，點擊臨近 “gnome” 的右箭頭。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/dconf-editor-clicking-gnome.png" alt="dconf editor clicking gnome"></p><p>接着在 “gnome” 下點擊 “gnome-session”。在右邊窗格里，選擇 “auto-save-session” 選項框並將它開啓。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/dconf-editor_selecting_auto_save_session.png" alt="dconf-editor selecting auto save session"></p><p>在你確認對剛才的選項打鈎之後，點擊默認情況下位於窗口左上角的關閉按鈕(X)來關閉 “Dconf Editor”。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/dconf-editor_closing_dconf_editor.png" alt="dconf-editor closing dconf editor"></p><p>在你登出並再登錄回來時，所有你正運行的應用就可以被還原了。</p><p>歡呼吧，我們已經成功地配置了我們的 Ubuntu 14.04 LTS &quot;Trusty&quot; 來自動記住我們上一次會話中正在運行的應用。</p><p>除了關機後恢復應用之外，還可以通過休眠來達成類似的功能。</p><p>###休眠功能</p><p>現在，在這個教程裏，我們也將學會 <strong>如何在 Ubuntu 14.04 LTS 裏開啓休眠功能</strong> :</p><p>在開始之前，在鍵盤上按 <code>Ctrl+Alt+T</code> 來開啓終端。在它開啓以後，運行：</p><pre><code>sudo pm-hibernate
</code></pre><p>在你的電腦關閉後，再重新開啓它。這時，你開啓的應用被重新打開了嗎？如果休眠功能沒有發揮作用，請檢查你的交換分區大小，它至少要和你可用 RAM 大小相當。</p><p>你可以在系統監視器裏查看你的交換分區大小，系統監視器可以通過在應用菜單或在終端裏運行下面的命令來開啓：</p><pre><code>$ gnome-system-monitor
</code></pre><h4 id="在系統托盤裏啓用休眠功能" tabindex="-1">在系統托盤裏啓用休眠功能: <a class="header-anchor" href="#在系統托盤裏啓用休眠功能" aria-label="Permalink to “在系統托盤裏啓用休眠功能:”">​</a></h4><p>系統托盤裏面的會話指示器現在使用 logind 而不是 upower 了。默認情況下，在 upower 和 logind 中，休眠菜單都被禁用了。</p><p>為了開啓它的休眠菜單，依次運行下面的命令來編輯配置文件：</p><pre><code>sudo -i

cd /var/lib/polkit-1/localauthority/50-local.d/

gedit com.ubuntu.enable-hibernate.pkla
</code></pre><p><strong>提示：假如對你來説，這個配置文件並沒有起到作用，請替換上面代碼中的 /var/lib 為 /etc 來試試另一個配置文件</strong></p><p>複製並粘貼下面的代碼到文件中並保存：</p><pre><code>[Re-enable hibernate by default in upower]
 Identity=unix-user:*
 Action=org.freedesktop.upower.hibernate
 ResultActive=yes

[Re-enable hibernate by default in logind]
 Identity=unix-user:*
 Action=org.freedesktop.login1.hibernate
 ResultActive=yes
</code></pre><p>重啓你的電腦就可以了。</p><h4 id="當你蓋上筆記本的後蓋時-讓它休眠" tabindex="-1">當你蓋上筆記本的後蓋時，讓它休眠: <a class="header-anchor" href="#當你蓋上筆記本的後蓋時-讓它休眠" aria-label="Permalink to “當你蓋上筆記本的後蓋時，讓它休眠:”">​</a></h4><ol><li><p>通過下面的命令編輯文件 “/etc/systemd/logind.conf” :</p><pre><code> $ sudo nano /etc/systemd/logind.conf
</code></pre></li><li><p>將 <strong>#HandleLidSwitch=suspend</strong> （掛起）這一行改為 <strong>HandleLidSwitch=hibernate</strong> （休眠）並保存文件；</p></li><li><p>運行下面的命令或重啓你的電腦來應用更改:</p><pre><code> $ sudo restart systemd-logind
</code></pre></li></ol><p>就是這樣。 成功了嗎？現在我們設置了 dconf 並開啓了休眠功能 😃 這樣，無論你是關機還是直接合上筆記本蓋子，你的 Ubuntu 將能夠完全記住你開啓的應用和窗口了。</p><hr>`,37)),p("p",null,[e[1]||(e[1]=o("via: ",-1)),n(t,{href:"http://linoxide.com/ubuntu-how-to/remember-running-applications-ubuntu/"},{default:i(()=>[...e[0]||(e[0]=[o("http://linoxide.com/ubuntu-how-to/remember-running-applications-ubuntu/",-1)])]),_:1})]),p("p",null,[e[5]||(e[5]=o("作者：",-1)),n(t,{href:"http://linoxide.com/author/arunp/"},{default:i(()=>[...e[2]||(e[2]=[o("Arun Pyasi",-1)])]),_:1}),e[6]||(e[6]=o(" 譯者：",-1)),n(t,{href:"https://github.com/FSSlc"},{default:i(()=>[...e[3]||(e[3]=[o("FSSlc",-1)])]),_:1}),e[7]||(e[7]=o(" 校對：",-1)),n(t,{href:"https://github.com/wxy"},{default:i(()=>[...e[4]||(e[4]=[o("wxy",-1)])]),_:1})]),p("p",null,[e[10]||(e[10]=o("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[8]||(e[8]=[o("LCTT",-1)])]),_:1}),e[11]||(e[11]=o(" 原創翻譯，",-1)),n(t,{href:"http://linux.cn/"},{default:i(()=>[...e[9]||(e[9]=[o("Linux中國",-1)])]),_:1}),e[12]||(e[12]=o(" 榮譽推出",-1))])])}const w=r(u,[["render",c]]);export{_ as __pageData,w as default};
